<?php require_once "../db.php";require_role("Admin");$r=$conn->query("SELECT q.title,COUNT(h.id) attempts,COALESCE(AVG((h.score/h.total_questions)*100),0) avg_percent FROM quiz q LEFT JOIN quiz_history h ON h.quiz_id=q.id GROUP BY q.id ORDER BY q.id DESC");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/admin_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2>Reports & Analysis</h2><div class="card panel-card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Quiz</th><th>Attempts</th><th>Average %</th></tr></thead><tbody><?php while($d=$r->fetch_assoc()):?><tr><td><?=e($d["title"])?></td><td><?=$d["attempts"]?></td><td><?=round($d["avg_percent"],1)?>%</td></tr><?php endwhile;?></tbody></table></div></div></div></main></div></div></body></html>
